namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Room { get; set; }
    public int DepartmentId { get; set; }
    public required Instructor Instructor { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Bio { get; set; }
    public required string Email { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
            new Department { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
            new Department { Id = 3, Name = "Physics", Abbreviation = "PHYS" },
            new Department { Id = 4, Name = "English", Abbreviation = "ENG" },
            new Department { Id = 5, Name = "History", Abbreviation = "HIST" },
        ];

        _courses =
        [
            new Course
            {
                Id = 1, Code = "CS 101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, IsFeatured = true,
                Instructor = new Instructor { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has over 15 years of experience in computer science education. She holds a Ph.D. from MIT and specializes in programming language design and pedagogy.", Email = "s.chen@university.edu" }
            },
            new Course
            {
                Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms",
                Description = "A study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms). Includes analysis of time and space complexity.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", DepartmentId = 1, IsFeatured = false,
                Instructor = new Instructor { Id = 2, Name = "Prof. James Rivera", Title = "Professor", Bio = "Prof. Rivera is an ACM Fellow whose research focuses on graph algorithms and combinatorial optimization. He has published over 80 peer-reviewed papers.", Email = "j.rivera@university.edu" }
            },
            new Course
            {
                Id = 3, Code = "CS 450", Title = "Machine Learning",
                Description = "Covers supervised and unsupervised learning, neural networks, support vector machines, and ensemble methods. Students complete a capstone project applying ML to a real-world dataset.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Center 110", DepartmentId = 1, IsFeatured = true,
                Instructor = new Instructor { Id = 3, Name = "Dr. Anika Patel", Title = "Assistant Professor", Bio = "Dr. Patel joined the faculty after completing postdoctoral research at Stanford's AI Lab. Her work focuses on explainable AI and fairness in machine learning systems.", Email = "a.patel@university.edu" }
            },
            new Course
            {
                Id = 4, Code = "MATH 201", Title = "Calculus II",
                Description = "Continuation of Calculus I. Topics include techniques of integration, applications of integrals, infinite sequences and series, parametric equations, and polar coordinates.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 102", DepartmentId = 2, IsFeatured = false,
                Instructor = new Instructor { Id = 4, Name = "Dr. Michael Torres", Title = "Professor", Bio = "Dr. Torres is an award-winning educator with 20 years of teaching experience. He has authored two widely adopted calculus textbooks.", Email = "m.torres@university.edu" }
            },
            new Course
            {
                Id = 5, Code = "MATH 310", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors, and inner product spaces. Applications to computer graphics and data science.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Math Building 204", DepartmentId = 2, IsFeatured = true,
                Instructor = new Instructor { Id = 5, Name = "Dr. Emily Nakamura", Title = "Associate Professor", Bio = "Dr. Nakamura's research spans numerical linear algebra and matrix computation. She is a recipient of the university's Distinguished Teaching Award.", Email = "e.nakamura@university.edu" }
            },
            new Course
            {
                Id = 6, Code = "PHYS 101", Title = "General Physics I",
                Description = "Introduction to classical mechanics, thermodynamics, and waves. Covers Newton's laws, energy conservation, rotational dynamics, and basic fluid mechanics. Includes weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Physics Lab 101", DepartmentId = 3, IsFeatured = false,
                Instructor = new Instructor { Id = 6, Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is a former NASA researcher who brings real-world physics applications into the classroom. He holds patents in materials science.", Email = "r.kim@university.edu" }
            },
            new Course
            {
                Id = 7, Code = "PHYS 320", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory including wave-particle duality, the Schrödinger equation, quantum states, operators, and measurement. Prerequisites: PHYS 201, MATH 310.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Physics Lab 302", DepartmentId = 3, IsFeatured = true,
                Instructor = new Instructor { Id = 7, Name = "Dr. Lisa Johansson", Title = "Associate Professor", Bio = "Dr. Johansson completed her doctorate at CERN and specializes in quantum computing and particle physics. She leads the university's Quantum Information Lab.", Email = "l.johansson@university.edu" }
            },
            new Course
